def algorithm(func, dim, lb, ub, budget, rng):
    X = np.random.uniform(lb, ub, size=(budget, dim))
    Y = np.zeros(budget)
    for i in range(1, budget):
        X_new = np.clip(X[i-1] + 0.05 * np.sign(np.random.normal(size=dim)) * np.random.normal(size=dim), lb, ub)
        Y[i] = func(X_new)
        if Y[i] < Y[i-1]:
            X[i:] = X_new
    return X[np.argmin(Y)]

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    x_best = np.random.uniform(lb, ub, size=(1, dim))
    f_best = func(x_best)
    temp = 10.0
    for i in range(budget):
        sigma = (ub - lb) / (temp * rng.uniform(0.1, 1.0))
        x_new = clip(x_best + np.random.normal(size=(1, dim), loc=0.0, scale=sigma))
        f_new = func(x_new)
        if f_new < f_best:
            x_best = x_new
            f_best = f_new
        temp *= 0.9999
    return x_best
